use std::process::exit;

use wgpu::util::DeviceExt;

const SHADER: &str = r#"
struct Params {
    count: u32,
    dt: f32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> pos: array<vec2<f32>>;
@group(0) @binding(2) var<storage, read_write> vel: array<vec2<f32>>;
@group(0) @binding(3) var<storage, read_write> acc: array<vec2<f32>>;

@compute @workgroup_size(64)
fn accelerate(@builtin(global_invocation_id) id: vec3<u32>) {
    let i = id.x;
    if (i >= params.count) {
        return;
    }
    let pi = pos[i];
    var a = vec2<f32>(0.0, 0.0);
    for (var j = 0u; j < params.count; j = j + 1u) {
        if (j == i) {
            continue;
        }
        let d = pos[j] - pi;
        let s = dot(d, d) + 0.01;
        a = a + d / (s * sqrt(s));
    }
    acc[i] = a;
}

@compute @workgroup_size(64)
fn integrate(@builtin(global_invocation_id) id: vec3<u32>) {
    let i = id.x;
    if (i >= params.count) {
        return;
    }
    let v = vel[i] + acc[i] * params.dt;
    vel[i] = v;
    pos[i] = pos[i] + v * params.dt;
}
"#;

fn fail(msg: &str) -> ! {
    eprintln!("{msg}");
    exit(1);
}

struct Input {
    steps: u32,
    dt: f32,
    pos: Vec<[f32; 2]>,
    vel: Vec<[f32; 2]>,
}

fn parse(path: &str) -> Result<Input, String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let mut tok = text.split_whitespace();
    let mut next = || tok.next().ok_or_else(|| "unexpected end of input".to_string());
    let count: usize = next()?.parse::<f64>().map_err(|e| e.to_string())? as usize;
    let steps: u32 = next()?.parse::<f64>().map_err(|e| e.to_string())? as u32;
    let dt: f32 = next()?.parse().map_err(|e: std::num::ParseFloatError| e.to_string())?;
    let mut pos = Vec::with_capacity(count);
    let mut vel = Vec::with_capacity(count);
    for _ in 0..count {
        let mut f = [0f32; 4];
        for v in f.iter_mut() {
            *v = next()?.parse().map_err(|e: std::num::ParseFloatError| e.to_string())?;
        }
        pos.push([f[0], f[1]]);
        vel.push([f[2], f[3]]);
    }
    Ok(Input { steps, dt, pos, vel })
}

fn read_back(device: &wgpu::Device, buf: &wgpu::Buffer, n: usize) -> Vec<[f32; 2]> {
    let slice = buf.slice(..);
    slice.map_async(wgpu::MapMode::Read, |r| r.expect("map failed"));
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .expect("poll failed");
    let data = slice.get_mapped_range();
    let out: Vec<[f32; 2]> = bytemuck::cast_slice::<u8, [f32; 2]>(&data)[..n].to_vec();
    drop(data);
    buf.unmap();
    out
}

fn run(input: &Input) -> (Vec<[f32; 2]>, Vec<[f32; 2]>) {
    let n = input.pos.len();
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions::default()))
        .unwrap_or_else(|_| fail("no GPU adapter"));
    let (device, queue) =
        pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))
            .unwrap_or_else(|e| fail(&format!("no device: {e}")));

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: None,
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });

    let mut params = Vec::new();
    params.extend_from_slice(&(n as u32).to_le_bytes());
    params.extend_from_slice(&input.dt.to_le_bytes());
    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: None,
        contents: &params,
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let storage = wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC;
    let pos_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: None,
        contents: bytemuck::cast_slice(&input.pos),
        usage: storage,
    });
    let vel_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: None,
        contents: bytemuck::cast_slice(&input.vel),
        usage: storage,
    });
    let size = (n * 8) as u64;
    let acc_buf = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage: storage,
        mapped_at_creation: false,
    });
    let staging = |label| {
        device.create_buffer(&wgpu::BufferDescriptor {
            label: Some(label),
            size,
            usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        })
    };
    let pos_stage = staging("pos stage");
    let vel_stage = staging("vel stage");

    let pipeline = |entry| {
        device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some(entry),
            layout: None,
            module: &module,
            entry_point: Some(entry),
            compilation_options: Default::default(),
            cache: None,
        })
    };
    let accelerate = pipeline("accelerate");
    let integrate = pipeline("integrate");

    let entry = |binding, buffer: &wgpu::Buffer| wgpu::BindGroupEntry {
        binding,
        resource: buffer.as_entire_binding(),
    };
    let entries = [
        entry(0, &params_buf),
        entry(1, &pos_buf),
        entry(2, &vel_buf),
        entry(3, &acc_buf),
    ];
    let group = |p: &wgpu::ComputePipeline| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: None,
            layout: &p.get_bind_group_layout(0),
            entries: &entries,
        })
    };
    let accelerate_group = group(&accelerate);
    let integrate_group = group(&integrate);

    let groups = (n as u32).div_ceil(64);
    let mut encoder = device.create_command_encoder(&Default::default());
    for _ in 0..input.steps {
        let mut pass = encoder.begin_compute_pass(&Default::default());
        pass.set_pipeline(&accelerate);
        pass.set_bind_group(0, &accelerate_group, &[]);
        pass.dispatch_workgroups(groups, 1, 1);
        pass.set_pipeline(&integrate);
        pass.set_bind_group(0, &integrate_group, &[]);
        pass.dispatch_workgroups(groups, 1, 1);
    }
    encoder.copy_buffer_to_buffer(&pos_buf, 0, &pos_stage, 0, size);
    encoder.copy_buffer_to_buffer(&vel_buf, 0, &vel_stage, 0, size);
    queue.submit([encoder.finish()]);

    (read_back(&device, &pos_stage, n), read_back(&device, &vel_stage, n))
}

fn clean(x: f64) -> String {
    let s = format!("{x:.6}");
    if s.starts_with('-') && s[1..].bytes().all(|b| b == b'0' || b == b'.') {
        s[1..].to_string()
    } else {
        s
    }
}

fn main() {
    let path = std::env::args().nth(1).unwrap_or_else(|| fail("usage: particles <file>"));
    let input = parse(&path).unwrap_or_else(|e| fail(&e));
    let n = input.pos.len();
    if n == 0 {
        fail("no particles");
    }
    let (pos, vel) = run(&input);

    let nf = n as f64;
    let cx = pos.iter().map(|p| p[0] as f64).sum::<f64>() / nf;
    let cy = pos.iter().map(|p| p[1] as f64).sum::<f64>() / nf;
    let mx: f64 = vel.iter().map(|v| v[0] as f64).sum();
    let my: f64 = vel.iter().map(|v| v[1] as f64).sum();
    let ke: f64 = vel
        .iter()
        .map(|v| (v[0] as f64 * v[0] as f64 + v[1] as f64 * v[1] as f64) / 2.0)
        .sum();
    let var = pos
        .iter()
        .map(|p| (p[0] as f64 - cx).powi(2) + (p[1] as f64 - cy).powi(2))
        .sum::<f64>()
        / nf;
    println!("CENTER {} {}", clean(cx), clean(cy));
    println!("MOMENTUM {} {}", clean(mx), clean(my));
    println!("KINETIC {}", clean(ke));
    println!("SPREAD {}", clean(var.sqrt()));
}
