fn parse(path: &str) -> Result<Input, String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let mut tok = text.split_whitespace();
    let mut next = || tok.next().ok_or_else(|| "unexpected end of input".to_string());
    let count: usize = next()?.parse::<f64>().map_err(|e| e.to_string())? as usize;
    let steps: u32 = next()?.parse::<f64>().map_err(|e| e.to_string())? as u32;
    let dt: f32 = next()?.parse().map_err(|e: std::num::ParseFloatError| e.to_string())?;
    let mut pos = Vec::with_capacity(count);
    let mut vel = Vec::with_capacity(count);
    for _ in 0..count {
        let mut f = [0f32; 4];
        for v in f.iter_mut() {
            *v = next()?.parse().map_err(|e: std::num::ParseFloatError| e.to_string())?;
