        .poll(wgpu::PollType::wait_indefinitely())
        .expect("poll failed");
    let data = slice.get_mapped_range();
    let out: Vec<[f32; 2]> = bytemuck::cast_slice::<u8, [f32; 2]>(&data)[..n].to_vec();
    drop(data);
    buf.unmap();
